Object.assign(SNIP,{});PRESET_NOTES["l15"]={"Ví dụ: Căn bậc hai nguyên": "Khoảng [lo, hi] co lại một nửa mỗi vòng: khoảng 31 vòng cho khoảng hai tỉ giá trị. hi = 2·10⁹ + 1 đủ cho mọi n ≤ 4·10¹⁸ mà mid·mid không tràn long long.", "Ví dụ: Chia sách cho k người chép": "ok(M) chia tham lam rồi đếm số đoạn. Vòng nhị phân chỉ gọi ok khoảng log₂(280) ≈ 9 lần. Đáp án 110: 10+20+30+40 | 50+60 | 70.", "Ví dụ: Đặt k điểm cách xa nhau nhất": "Lần này tìm giá trị lớn nhất còn đạt được, nên lo là phía “đúng”. Kiểm tra tham lam: đặt điểm đầu ở vị trí nhỏ nhất, mỗi điểm sau đặt ở vị trí sớm nhất cách điểm trước ≥ mid. Kết quả 5 (đặt ở 1, 8, 13; khoảng cách 6 thì chỉ đặt được 2 con)."};EX_HINTS["l15"]=[["Giữ bất biến lo · lo ≤ n và hi · hi > n. n ≤ 10¹⁸ nên hi = 10⁹ + 1 là đủ, và mid · mid ≤ 10¹⁸ không tràn long long.", "Đừng dùng sqrt của thư viện: số thực double không đủ chính xác với n gần 10¹⁸."], ["Chia được thành ≤ k đoạn thì cũng chia được thành đúng k đoạn (tách bớt một đoạn dài, vì k ≤ n). Nên kiểm tra “số đoạn ≤ k”.", "lo = 0 (chắc chắn không được), hi = tổng cả dãy (chắc chắn được); trả về hi."], ["ok(d): đặt tham lam từ trái, mỗi con ở chuồng sớm nhất cách con trước ≥ d; đặt được ≥ k con thì d đạt được.", "Các vị trí khác nhau nên d = 1 luôn đạt được (lo = 1), d = x_max − x_min + 1 không bao giờ đạt (hi)."]];
