const PR15=[{label:"Ví dụ: Căn bậc hai nguyên",input:"1000000",code:"#include <iostream>\nusing namespace std;\n\nint main() {\n    long long n;\n    cin >> n;\n    // tìm v lớn nhất có v * v <= n: lo luôn thỏa, hi luôn không thỏa\n    long long lo = 0, hi = 2000000001;\n    while (hi - lo > 1) {\n        long long mid = lo + (hi - lo) / 2;\n        if (mid * mid <= n) lo = mid;\n        else hi = mid;\n    }\n    cout << lo << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["lo","mid","hi"]}],py:{code:"n = int(input())\n# tìm v lớn nhất có v * v <= n: lo luôn thỏa, hi luôn không thỏa\nlo, hi = 0, n + 1\nwhile hi - lo > 1:\n    mid = (lo + hi) // 2\n    if mid * mid <= n:\n        lo = mid\n    else:\n        hi = mid\nprint(lo)",note:"Khoảng [lo, hi] co lại một nửa mỗi vòng: khoảng 20 vòng cho n = 10⁶, khoảng 60 vòng cho n = 10¹⁸. Số nguyên Python không tràn nên chọn hi = n + 1 cho đơn giản."},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        long n = long.Parse(Console.ReadLine());\n        // tìm v lớn nhất có v * v <= n: lo luôn thỏa, hi luôn không thỏa\n        long lo = 0, hi = 2000000001;\n        while (hi - lo > 1)\n        {\n            long mid = lo + (hi - lo) / 2;\n            if (mid * mid <= n) lo = mid;\n            else hi = mid;\n        }\n        Console.WriteLine(lo);\n    }\n}"}},{label:"Ví dụ: Chia sách cho k người chép",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nvector<int> a = {10, 20, 30, 40, 50, 60, 70};\nint k = 3;\n\nbool ok(long long M) {\n    int doan = 1;\n    long long tong = 0;\n    for (int x : a) {\n        if (x > M) return false;\n        if (tong + x > M) {\n            doan++;\n            tong = 0;\n        }\n        tong += x;\n    }\n    return doan <= k;\n}\n\nint main() {\n    long long lo = 0, hi = 0;\n    for (int x : a) hi += x;      // ok(hi) chắc chắn đúng\n    while (hi - lo > 1) {\n        long long mid = lo + (hi - lo) / 2;\n        if (ok(mid)) hi = mid;\n        else lo = mid;\n    }\n    cout << hi << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a"},{type:"vars",names:["lo","mid","hi","doan","tong"]}],py:{code:"a = [10, 20, 30, 40, 50, 60, 70]\nk = 3\n\ndef ok(M):\n    doan = 1\n    tong = 0\n    for x in a:\n        if x > M:\n            return False\n        if tong + x > M:\n            doan += 1\n            tong = 0\n        tong += x\n    return doan <= k\n\nlo, hi = 0, sum(a)      # ok(hi) chắc chắn đúng\nwhile hi - lo > 1:\n    mid = (lo + hi) // 2\n    if ok(mid):\n        hi = mid\n    else:\n        lo = mid\nprint(hi)"},cs:{code:"using System;\n\nclass Program\n{\n    static int[] a = { 10, 20, 30, 40, 50, 60, 70 };\n    static int k = 3;\n\n    static bool Ok(long M)\n    {\n        int doan = 1;\n        long tong = 0;\n        foreach (int x in a)\n        {\n            if (x > M) return false;\n            if (tong + x > M)\n            {\n                doan++;\n                tong = 0;\n            }\n            tong += x;\n        }\n        return doan <= k;\n    }\n\n    static void Main()\n    {\n        long lo = 0, hi = 0;\n        foreach (int x in a) hi += x;      // Ok(hi) chắc chắn đúng\n        while (hi - lo > 1)\n        {\n            long mid = lo + (hi - lo) / 2;\n            if (Ok(mid)) hi = mid;\n            else lo = mid;\n        }\n        Console.WriteLine(hi);\n    }\n}",note:"a và k là biến static của lớp: mọi hàm static (Main, Ok) đều dùng được. Ok(M) chia tham lam rồi đếm số đoạn; tìm kiếm nhị phân tìm M nhỏ nhất làm Ok đúng."}},{label:"Ví dụ: Đặt k điểm cách xa nhau nhất",input:"",code:"#include <iostream>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int x[6] = {1, 2, 8, 4, 9, 13};\n    int n = 6, k = 3;\n    sort(x, x + n);\n    int lo = 0, hi = x[n - 1] - x[0] + 1;   // khoảng cách lo đạt được, hi thì không\n    while (hi - lo > 1) {\n        int mid = lo + (hi - lo) / 2;\n        int dem = 1, cuoi = x[0];\n        for (int i = 1; i < n; i++) {\n            if (x[i] - cuoi >= mid) {\n                dem++;\n                cuoi = x[i];\n            }\n        }\n        if (dem >= k) lo = mid;\n        else hi = mid;\n    }\n    cout << lo << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"x"},{type:"vars",names:["lo","mid","hi","dem"]}],py:{code:"x = [1, 2, 8, 4, 9, 13]\nn, k = 6, 3\nx.sort()\nlo, hi = 0, x[n - 1] - x[0] + 1   # khoảng cách lo đạt được, hi thì không\nwhile hi - lo > 1:\n    mid = (lo + hi) // 2\n    dem = 1\n    cuoi = x[0]\n    for i in range(1, n):\n        if x[i] - cuoi >= mid:\n            dem += 1\n            cuoi = x[i]\n    if dem >= k:\n        lo = mid\n    else:\n        hi = mid\nprint(lo)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] x = { 1, 2, 8, 4, 9, 13 };\n        int n = 6, k = 3;\n        Array.Sort(x);\n        int lo = 0, hi = x[n - 1] - x[0] + 1;   // khoảng cách lo đạt được, hi thì không\n        while (hi - lo > 1)\n        {\n            int mid = lo + (hi - lo) / 2;\n            int dem = 1, cuoi = x[0];\n            for (int i = 1; i < n; i++)\n            {\n                if (x[i] - cuoi >= mid)\n                {\n                    dem++;\n                    cuoi = x[i];\n                }\n            }\n            if (dem >= k) lo = mid;\n            else hi = mid;\n        }\n        Console.WriteLine(lo);\n    }\n}"}}];
