makeEx2(document.getElementById("ex-l15"),sim15,[{t:"Căn bậc hai nguyên",d:"Đầu vào: một số nguyên n (0 ≤ n ≤ 10^18). Đầu ra: số nguyên v lớn nhất thỏa v · v ≤ n.",tests:[{in:"30",out:"5"},{in:"0",out:"0"},{in:"1",out:"1"},{in:"1000000000000000000",out:"1000000000"},{in:"999999999999999999",out:"999999999"},{in:"15",out:"3"}],start:"#include <iostream>\nusing namespace std;\n\nint main() {\n    long long n;\n    cin >> n;\n    // tìm kiếm nhị phân trên v; cẩn thận tràn số khi tính v * v\n    return 0;\n}",perf:{gen:n=>String(n),ns:[1000000,100000000,10000000000],need:"logn",limit:n=>2000,why:"Thử lần lượt v = 0, 1, 2, … tốn O(√n) bước, quá chậm với n = 10¹⁸. Tìm kiếm nhị phân chỉ cần khoảng 30 vòng."},py:{start:"n = int(input())\n# tìm kiếm nhị phân trên v",hints:["Giữ bất biến lo · lo ≤ n và hi · hi > n. n ≤ 10¹⁸ nên hi = 10⁹ + 1 là đủ.","Đừng dùng n ** 0.5 hay math.sqrt: số thực không đủ chính xác với n gần 10¹⁸ (Python có math.isqrt làm đúng việc này)."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        long n = long.Parse(Console.ReadLine());\n        // tìm kiếm nhị phân trên v; cẩn thận tràn số khi tính v * v\n    }\n}",hints:["Giữ bất biến lo · lo ≤ n và hi · hi > n. n ≤ 10¹⁸ nên hi = 10⁹ + 1 là đủ, và mid · mid ≤ 10¹⁸ không tràn long.","Đừng dùng Math.Sqrt: số thực double không đủ chính xác với n gần 10¹⁸."]}},{t:"Chia dãy thành k đoạn",d:"Đầu vào: n và k (1 ≤ k ≤ n ≤ 10^5), rồi n số nguyên dương (≤ 10^9). Đầu ra: giá trị nhỏ nhất có thể của tổng lớn nhất khi chia dãy thành đúng k đoạn liên tiếp khác rỗng.",tests:[{in:"7 3\n10 20 30 40 50 60 70",out:"110"},{in:"1 1\n5",out:"5"},{in:"5 5\n3 1 4 1 5",out:"5"},{in:"5 1\n3 1 4 1 5",out:"14"},{in:"4 2\n1000000000 1000000000 1000000000 1000000000",out:"2000000000"}],start:"#include <iostream>\nusing namespace std;\n\nlong long a[100000];\nint n, k;\n\nbool ok(long long M) {\n    // chia tham lam: mỗi đoạn tổng <= M; đếm số đoạn\n    return false;\n}\n\nint main() {\n    cin >> n >> k;\n    for (int i = 0; i < n; i++) cin >> a[i];\n    return 0;\n}",perf:{gen:n=>n+" "+(n>>3||1)+"\n"+Array.from({length:n},(_,i)=>1+(i*7919)%1000).join(" "),ns:[250,1000,4000],need:"nlogn",limit:n=>14*n*Math.log2(n*1000)+30*n+200,why:"Thử mọi giá trị M từ nhỏ tới lớn tốn O(n · tổng). Tìm kiếm nhị phân trên M chỉ cần O(n log(tổng))."},py:{start:"n, k = map(int, input().split())\na = list(map(int, input().split()))\n\ndef ok(M):\n    # chia tham lam: mỗi đoạn tổng <= M; đếm số đoạn\n    return False",hints:["Chia được thành ≤ k đoạn thì cũng chia được thành đúng k đoạn (tách bớt một đoạn dài, vì k ≤ n). Nên kiểm tra “số đoạn ≤ k”.","lo = 0 (chắc chắn không được), hi = sum(a) (chắc chắn được); in hi."]},cs:{start:"using System;\n\nclass Program\n{\n    static long[] a;\n    static int n, k;\n\n    static bool Ok(long M)\n    {\n        // chia tham lam: mỗi đoạn tổng <= M; đếm số đoạn\n        return false;\n    }\n\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        n = int.Parse(t[0]);\n        k = int.Parse(t[1]);\n        a = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        // tìm M nhỏ nhất để Ok(M) đúng\n    }\n}",hints:["Chia được thành ≤ k đoạn thì cũng chia được thành đúng k đoạn (tách bớt một đoạn dài, vì k ≤ n). Nên kiểm tra “số đoạn ≤ k”.","lo = 0 (chắc chắn không được), hi = tổng cả dãy (chắc chắn được); trả về hi.","a, n, k khai báo static để hàm Ok dùng được."]}},{t:"Chuồng bò",d:"Đầu vào: n và k (2 ≤ k ≤ n ≤ 10^5), rồi n số nguyên đôi một khác nhau (0 ≤ xᵢ ≤ 10^9): vị trí các chuồng trên một đường thẳng, chưa sắp xếp. Đầu ra: khoảng cách nhỏ nhất giữa hai con bò lớn nhất có thể khi đặt k con bò vào k chuồng khác nhau.",tests:[{in:"5 3\n1 2 8 4 9",out:"3"},{in:"2 2\n0 1000000000",out:"1000000000"},{in:"4 4\n1 2 3 4",out:"1"},{in:"6 3\n1 2 8 4 9 13",out:"5"}],start:"#include <iostream>\n#include <algorithm>\nusing namespace std;\n\nint x[100000];\nint n, k;\n\nint main() {\n    cin >> n >> k;\n    for (int i = 0; i < n; i++) cin >> x[i];\n    // sắp xếp; tìm khoảng cách d lớn nhất còn đặt được k con\n    return 0;\n}",perf:{gen:n=>n+" "+(n>>2||2)+"\n"+Array.from({length:n},(_,i)=>(i*7919)%1000000).join(" "),ns:[250,1000,4000],need:"nlogn",limit:n=>60*n*Math.log2(n)+30*30*n+200,why:"Thử mọi khoảng cách d tốn O(n · khoảng tọa độ). Tìm kiếm nhị phân trên d: O(n log n + n log(tọa độ))."},py:{start:"n, k = map(int, input().split())\nx = list(map(int, input().split()))\n# sắp xếp; tìm khoảng cách d lớn nhất còn đặt được k con",hints:["ok(d): đặt tham lam từ trái, mỗi con ở chuồng sớm nhất cách con trước ≥ d; đặt được ≥ k con thì d đạt được.","Các vị trí khác nhau nên d = 1 luôn đạt được (lo = 1), d = x_max − x_min + 1 không bao giờ đạt (hi)."]},cs:{start:"using System;\n\nclass Program\n{\n    static int[] x;\n    static int n, k;\n\n    static void Main()\n    {\n        string[] t = Console.ReadLine().Split();\n        n = int.Parse(t[0]);\n        k = int.Parse(t[1]);\n        x = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        // sắp xếp; tìm khoảng cách d lớn nhất còn đặt được k con\n    }\n}",hints:["Ok(d): đặt tham lam từ trái, mỗi con ở chuồng sớm nhất cách con trước ≥ d; đặt được ≥ k con thì d đạt được.","Các vị trí khác nhau nên d = 1 luôn đạt được (lo = 1), d = x_max − x_min + 1 không bao giờ đạt (hi)."]}}]);

